+    if (existente) {
+      return res.status(200).json(serializarCertificado(existente));
+    }
+    const cargaHorariaMinutos = Math.round(
+      encontrosDaAtividade.reduce(
+        (soma, e) => soma + (Date.parse(e.fim) - Date.parse(e.inicio)) / 60000,
+        0,
+      ),
+    );
+    const codigo = gerarCodigoCertificado();
+    const emitidoEm = agora().toISOString();
+    try {
+      inserirCertificado.run(codigo, atividade.id, req.usuario.id, cargaHorariaMinutos, totalPresencas, totalEncontros, emitidoEm);
+    } catch (erro) {
+      const ehConflito = erro && typeof erro.code === 'string' && erro.code.startsWith('SQLITE_CONSTRAINT');
+      if (ehConflito) {
+        const concorrente = certificadoPorAtividadeEParticipante.get(atividade.id, req.usuario.id);
+        if (concorrente) {
+          return res.status(200).json(serializarCertificado(concorrente));
+        }
+      }
+      throw erro;
+    }
+    return res.status(201).json({
+      codigo,
+      atividadeId: atividade.id,
+      participanteId: req.usuario.id,
+      cargaHorariaMinutos,
+      presencas: totalPresencas,
+      encontros: totalEncontros,
+      emitidoEm,
+    });
+  });
+
+  app.get('/certificados', exigirUsuario, exigirParticipante, (req, res) => {
+    res.json(certificadosDoParticipante.all(req.usuario.id).map(serializarCertificado));
+  });
+
+  // M5 — Painel da organização
+  const listaAtividadesPainel = banco.prepare(`
+    SELECT id, titulo, tipo, salaId, vagas, cancelada FROM atividades WHERE cancelada = 0 ORDER BY titulo COLLATE NOCASE
+  `);
+
+  function calcularOcupacaoPercentual(atividadeId) {
+    const atividade = banco.prepare('SELECT vagas FROM atividades WHERE id = ?').get(atividadeId);
+    if (!atividade) return 0;
+    const inscricoes = banco.prepare('SELECT status FROM inscricoes WHERE atividadeId = ?').all(atividadeId);
+    const ocupadas = contarVagasOcupadas(inscricoes);
+    if (atividade.vagas === 0) return 0;
+    return Math.round((ocupadas / atividade.vagas) * 1000) / 10;
+  }
+
+  function frequenciaPercentualAtividade(atividadeId) {
+    const encontros = encontrosPorAtividade.all(atividadeId);
+    const encontrosEncerados = encontros.filter((e) => {
+      const fimMs = Date.parse(e.fim);
+      return fimMs <= agora().getTime();
+    });
+    if (encontrosEncerados.length === 0) return null;
+    const totalMinutos = encontrosEncerados.reduce(
+      (soma, e) => soma + (Date.parse(e.fim) - Date.parse(e.inicio)) / 60000,
+      0,
+    );
+    const mediaMinutos = totalMinutos / encontrosEncerados.length;
+    return Math.round(mediaMinutos * 10) / 10;
+  }
+
+  function participantesSemChance(atividadeId) {
+    const confirmadas = banco.prepare(
+      "SELECT id, participanteId FROM inscricoes WHERE atividadeId = ? AND status = 'confirmada'",
+    ).all(atividadeId);
+    const resultado = [];
+
+    for (const insc of confirmadas) {
+      const participanteId = insc.participanteId;
+      const presencas = banco.prepare(
+        'SELECT id, encontroId, origem FROM presencas WHERE participanteId = ? AND encontroId IN (SELECT id FROM encontros WHERE atividadeId = ?)',
+      ).all(participanteId, atividadeId);
+
+      let faltasContadas = 0;
+      const encontros = banco.prepare('SELECT id, inicio, fim FROM encontros WHERE atividadeId = ? ORDER BY inicio').all(atividadeId);
+      const agoraMs = agora().getTime();
+
+      for (const enc of encontros) {
+        // Verifica se houve presença registrada para este encontro
+        const temPresenca = banco.prepare(
+          'SELECT id FROM presencas WHERE encontroId = ? AND participanteId = ?',
+        ).get(enc.id, participanteId);
+
+        if (!temPresenca) {
+          // Ausente - conta como falta
+          faltasContadas += 1;
+        } else {
+          // Verifica se o prazo de registro venceu (2h após fim do encontro)
+          const fimMs = Date.parse(enc.fim);
+          const prazoLimite = fimMs + 2 * 3600 * 1000;
+          if (agoraMs > prazoLimite) {
+            // Mesmo com presença registrada, se o prazo venceu, conta como falta
+            // (participante pode ter se inscrito mas não conseguiu registrar a presença a tempo)
+            faltasContadas += 1;
+          }
+        }
+      }
+      if (faltasContadas > 1) {
+        const usuario = usuarioPorId.get(participanteId);
+        if (usuario) {
+          resultado.push({
+            participanteId,
+            nome: usuario.nome,
+            faltas: faltasContadas,
+            faltasPermitidas: 1,
+          });
+        }
+      }
+    }
+    return resultado;
+  }
+
+  function gerarCSVFrecuencia(atividadeId) {
+    const atividade = banco.prepare('SELECT titulo FROM atividades WHERE id = ?').get(atividadeId);
+    if (!atividade) return '';
+
+    const confirmadas = banco.prepare(
+      "SELECT participanteId FROM inscricoes WHERE atividadeId = ? AND status = 'confirmada' ORDER BY participanteId COLLATE NOCASE",
+    ).all(atividadeId);
+
+    let csv = '\uFEFF'; // UTF-8 with BOM
+    csv += 'nome';
+
+    // Colunas E1...En para cada encontro
+    const encontros = encontrosPorAtividade.all(atividadeId).sort((a, b) => Date.parse(a.inicio) - Date.parse(b.inicio));
+    for (let i = 0; i < encontros.length; i++) {
+      csv += `;E${i + 1}`;
+    }
+    csv += ';frequencia;certificado';
+
+    for (const insc of confirmadas) {
+      const participanteId = insc.participanteId;
+      const usuario = usuarioPorId.get(participanteId);
+      if (!usuario) continue;
+
+      const nome = usuario.nome;
+      let linha = nome;
+
+      // Para cada encontro, marcar P, F ou -
+      for (const encontro of encontros) {
+        const presenca = banco.prepare(
+          'SELECT origem, justificativa FROM presencas WHERE encontroId = ? AND participanteId = ?',
+          encontro.id,
+          participanteId,
+        ).get();
+        const fimMs = Date.parse(encontro.fim);
+        const prazoLimite = fimMs + 2 * 3600 * 1000;
+        const agoraMs = agora().getTime();
+
+        if (agoraMs > prazoLimite) {
+          // Prazo vencido
+          if (!presenca) {
+            linha += ';F'; // Falta prazo vencido sem presença
+          } else if (presenca.origem === 'manual') {
+            linha += ';P'; // Presença manual (contaria como presente)
+          } else {
+            linha += ';F'; // Prazo vencido sem presença registrada
+          }
+        } else {
+          // Prazo aberto (hífen)
+          linha += ';-';
+        }
+      }
+
+      // Frequência calculada
+      const freq = frequenciaPercentualAtividade(atividadeId);
+      linha += `;${freq !== null ? freq.toFixed(1) : '0,0'}`;
+
+      // Certificado
+      const temCertificado = banco.prepare(
+        'SELECT id FROM certificados WHERE atividadeId = ? AND participanteId = ?',
+        atividadeId,
+        participanteId,
+      ).get();
+      linha += `;${temCertificado ? 'SIM' : 'NÃO'}`;
+
+      csv += `\n${linha}`;
+    }
+
+    return csv;
+  }
+
+  app.get('/painel/atividades', exigirUsuario, exigirOrganizacao, (req, res) => {
+    const linhas = listaAtividadesPainel.all();
+    const resultado = linhas.map((linha) => {
+      const ocupacaoPercentual = calcularOcupacaoPercentual(linha.id);
+      const frequenciaPercentual = frequenciaPercentualAtividade(linha.id);
+      return {
+        atividadeId: linha.id,
+        titulo: linha.titulo,
+        vagas: linha.vagas,
+        ocupadas: 0, // will be calculated below
+        emEspera: 0,
+        ocupacaoPercentual,
+        frequenciaPercentual,
+      };
+    });
+
+    // Recalcular ocupadas reais
+    for (const item of resultado) {
+      const inscricoes = banco.prepare('SELECT status FROM inscricoes WHERE atividadeId = ?').all(item.atividadeId);
+      item.ocupadas = contarVagasOcupadas(inscricoes);
+    }
+
+    res.json(resultado);
+  });
+
+  app.get('/painel/atividades/:id/sem-chance', exigirUsuario, exigirOrganizacao, (req, res) => {
+    const semChance = participantesSemChance(req.params.id);
+    res.json(semChance);
+  });
+
+  app.get('/painel/atividades/:id/frequencia.csv', exigirUsuario, exigirOrganizacao, (req, res) => {
+    const csv = gerarCSVFrecuencia(req.params.id);
+    const atividade = banco.prepare('SELECT titulo FROM atividades WHERE id = ?').get(req.params.id);
+    if (!atividade) {
+      return res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Atividade inexistente.' });
+    }
+    const mimeType = 'text/csv; charset=utf-8';
+    res.set('Content-Type', mimeType);
+    res.set('Content-Disposition', `attachment; filename="frequencia-${atividade.titulo}.csv"`);
+    res.status(200).send(csv);
+  });
+
+  app.get('/painel/bloqueios', exigirUsuario, exigirOrganizacao, (req, res) => {
+    // Implementar lógica de bloqueio
+    // Um participante fica bloqueado se confirmado em 2 atividades encerradas com zero presença
+    const atividades = banco.prepare('SELECT id, cancelada FROM atividades WHERE cancelada = 0').all();
+    const bloqueios = [];
+
+    for (const atv of atividades) {
+      const confirmadas = banco.prepare(
+        "SELECT participanteId, COUNT(*) as total FROM inscricoes WHERE atividadeId = ? AND status = 'confirmada' GROUP BY participanteId",
+        atv.id,
+      ).all();
+
+      for (const conf of confirmadas) {
+        const participanteId = conf.participanteId;
+
+        // Contar faltas: participante confirmado com 0 presenças nas atividades encerradas
+        const encontrosEncerados = encontrosPorAtividade.all(atv.id).filter((e) => {
+          const fimMs = Date.parse(e.fim);
+          return fimMs <= agora().getTime();
+        });
+
+        let faltaCount = 0;
+        for (const enc of encontrosEncerados) {
+          const temPresenca = banco.prepare(
+            'SELECT id FROM presencas WHERE encontroId = ? AND participanteId = ?',
+          ).get(enc.id, participanteId);
+          if (!temPresenca) {
+            faltaCount += 1;
+          }
+        }
+
+        if (faltaCount >= 2) {
+          // Já está bloqueado ou adicionar à lista
+          const existente = bloqueios.find((b) => b.participanteId === participanteId);
+          if (existente) {
+            existente.atividades.push(atv.id);
+          } else {
+            bloqueios.push({
+              participanteId,
+              nome: usuarioPorId.get(participanteId)?.nome || participanteId,
+              atividades: [atv.id],
+              bloqueadoDesde: new Date(agora().getTime()).toISOString(),
+            });
+          }
+        }
+      }
+    }
+    res.json(bloqueios);
+  });
+
+  app.delete('/painel/bloqueios/:participanteId', exigirUsuario, exigirOrganizacao, (req, res) => {
+    // Remover bloqueio - após desbloqueio, apenas atividades encerradas depois contam
+    const result = banco.prepare('DELETE FROM bloqueios WHERE participanteId = ?').run(req.params.participanteId);
+    if (result.changes === 0) {
+      return res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Bloqueio inexistente.' });
+    }
+    res.status(204).end();
+  });
+
+  function abreviarNome(nomeCompleto) {
+    const particulas = new Set(['de', 'da', 'do', 'das', 'dos']);
+    const partes = nomeCompleto.trim().split(/\s+/);
+    const primeiro = partes[0];
+    const resto = partes.slice(1).map((parte) => {
+      if (particulas.has(parte.toLowerCase())) {
+        return parte.toLowerCase();
+      }
+      return `${parte[0].toUpperCase()}.`;
+    });
+    return [primeiro, ...resto].join(' ');
+  }
+
+  app.get('/certificados/:codigo', (req, res) => {
+    const linha = certificadoPorCodigo.get(req.params.codigo);
+    if (!linha) {
+      return res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Certificado inexistente.' });
+    }
+    const usuario = usuarioPorId.get(linha.participanteId);
+    const atividade = banco.prepare('SELECT titulo FROM atividades WHERE id = ?').get(linha.atividadeId);
+    return res.json({
+      codigo: linha.codigo,
+      participante: abreviarNome(usuario.nome),
+      atividade: atividade.titulo,
+      cargaHorariaMinutos: linha.cargaHorariaMinutos,
+      emitidoEm: linha.emitidoEm,
+    });
+  });
+
+  app.get('/extrato', exigirUsuario, exigirParticipante, (req, res) => {
+    const participanteId = req.usuario.id;
+    const agoraMs = agora().getTime();
+    const atividades = banco.prepare('SELECT id, titulo, tipo, cancelada FROM atividades WHERE cancelada = 0').all();
+    const itens = [];
+    let palestrasMinutos = 0;
+    let minicursosMinutos = 0;
+    for (const atividade of atividades) {
+      const inscricao = banco.prepare("SELECT id FROM inscricoes WHERE atividadeId = ? AND participanteId = ? AND status = 'confirmada'").get(atividade.id, participanteId);
+      if (!inscricao) continue;
+      const encontros = encontrosPorAtividade.all(atividade.id);
+      if (encontros.length === 0) continue;
+      if (agoraMs < Date.parse(encontros[encontros.length - 1].fim)) continue;
+      const totalPresencas = contarPresencasCertificado.get(atividade.id, participanteId).total;
+      if (totalPresencas * 4 < encontros.length * 3) continue;
+      const cargaHorariaMinutos = Math.round(encontros.reduce((soma, e) => soma + (Date.parse(e.fim) - Date.parse(e.inicio)) / 60000, 0));
+      if (atividade.tipo === 'palestra') palestrasMinutos += cargaHorariaMinutos;
+      else minicursosMinutos += cargaHorariaMinutos;
+      const certificado = certificadoPorAtividadeEParticipante.get(atividade.id, participanteId);
+      itens.push({ atividadeId: atividade.id, titulo: atividade.titulo, tipo: atividade.tipo, cargaHorariaMinutos, codigo: certificado ? certificado.codigo : null });
+    }
+    const totalMinutos = palestrasMinutos + minicursosMinutos;
+    const aproveitadoMinutos = Math.min(Math.min(palestrasMinutos, 240) + minicursosMinutos, 1200);
+    return res.json({ itens, palestrasMinutos, minicursosMinutos, totalMinutos, aproveitadoMinutos });
+  });
+
+  return app;
 }
